function lesson(row: Lesson): Lesson {
  return row;
}

const lessons: Lesson[] = [
  lesson({ id: 'droit-naissance', competenceId: 'droit-travail', minutes: 5, concept: 'Un contrat de travail existe dès qu’un travail est fait contre un salaire.', de: { title: 'Entstehung des Arbeitsvertrags' }, checklist: ['Dire ce que chacune des deux personnes doit', 'Citer le temps partiel régulier', 'Ne pas exiger un écrit quand la loi n’en demande pas'], source: CO, screens: [
    { id: 's1', concept: 'Le contrat échange un travail contre un salaire.', title: 'Deux promesses', body: 'L’article 319 du code des obligations décrit le contrat individuel de travail. Une personne s’engage à travailler au service d’une autre. L’autre paie un salaire selon le temps ou selon le travail fait. C’est le cœur du rapport, avant le titre du poste.' },
    { id: 's2', concept: 'Le temps partiel régulier est aussi un contrat de travail.', title: 'Heures, demi-journées, journées', body: 'Le même article vise la personne qui travaille régulièrement par heures, demi-journées ou journées. Un petit taux d’occupation ne sort pas du droit du travail. Les vacances et les délais se lisent ensuite au prorata, pas en dehors du contrat.' },
    { id: 's3', concept: 'L’écrit n’est pas la règle générale.', title: 'Sans papier, le contrat peut exister', body: 'Sauf disposition contraire de la loi, le contrat n’est soumis à aucune forme spéciale. Il est aussi réputé conclu quand l’employeur accepte, pour un temps donné, un travail qui ne se fait d’après les circonstances que contre un salaire. L’écrit reste utile pour prouver un délai, un temps d’essai plus long ou une majoration écartée.' },
  ] }),
  lesson({ id: 'droit-temps', competenceId: 'droit-travail', minutes: 6, concept: 'La durée du travail a un plafond légal distinct des heures prévues au contrat.', de: { title: 'Höchstarbeitszeit und Pausen' }, checklist: ['Séparer 45 h et 50 h', 'Placer les pauses selon la longueur du jour', 'Garder 11 heures de repos'], source: LTR, screens: [
    { id: 's1', concept: 'Le plafond hebdomadaire dépend du type de travail.', title: '45 ou 50 heures', body: 'L’article 9 de la loi sur le travail fixe la durée maximale de la semaine : 45 heures pour l’industrie, le personnel de bureau, le personnel technique et la vente des grandes entreprises de commerce de détail. Elle est de 50 heures pour les autres travailleurs. Le contrat peut prévoir moins. Il ne peut pas dépasser le plafond sans les prolongations prévues par l’ordonnance.', figureId: 'ltr_45' },
    { id: 's2', concept: 'La pause grandit avec la journée.', title: 'Quart d’heure, demi-heure, heure', body: 'L’article 15 interrompt le travail par une pause d’au moins un quart d’heure si la journée dépasse cinq heures et demie, une demi-heure au-delà de sept heures, et une heure au-delà de neuf heures. Si la personne ne peut pas quitter sa place, la pause compte comme travail.' },
    { id: 's3', concept: 'Le repos quotidien est de onze heures consécutives.', title: 'Entre deux jours', body: 'L’article 15a donne au moins onze heures consécutives. Pour un adulte, ce repos peut descendre à huit heures une fois par semaine, si la moyenne sur deux semaines atteint onze heures. Ce n’est pas une pause au milieu du jour : c’est la nuit entre deux prestations.', figureId: 'ltr_rest' },
  ] }),
  lesson({ id: 'assur-carte', competenceId: 'assurances', minutes: 6, concept: 'Chaque assurance sociale couvre un risque différent.', de: { title: 'Karte der Sozialversicherungen' }, checklist: ['Nommer le risque de chaque sigle', 'Séparer 1er pilier, chômage, accident et 2e pilier', 'Ne pas confondre IJM et LAA'], source: OFAS, screens: [
    { id: 's1', concept: 'AVS, AI et APG forment le premier pilier salarial.', title: 'Vieillesse, invalidité, perte de gain', body: 'L’AVS vise la vieillesse et les survivants, l’AI l’invalidité, les APG notamment le service, la maternité et d’autres pertes de gain prévues par la loi. Sur le salaire, les trois se retiennent ensemble. En 2026 la part salariée lue sur le tableau OFAS est de 5,3 %, sans plafond de salaire.', figureId: 'avs_ai_apg' },
    { id: 's2', concept: 'L’AC, la LAA et la LPP ne couvrent pas le même événement.', title: 'Trois autres colonnes', body: 'L’assurance-chômage couvre la perte d’emploi dans les limites de la LACI. La LAA couvre l’accident et la maladie professionnelle, pas la maladie ordinaire. La LPP est le deuxième pilier : elle épargne un salaire coordonné, elle ne remplace pas l’AVS. L’indemnité journalière maladie est un autre contrat, souvent privé ou de CCT.' },
    { id: 's3', concept: 'Les allocations familiales ont un plancher fédéral et un montant cantonal.', title: 'Enfant et formation', body: 'Le minimum fédéral lu sur la page OFAS est de 215 francs par mois pour l’enfant et de 268 francs pour la formation. Le canton peut prévoir plus. L’aperçu des montants cantonaux dit lui-même que seule la loi cantonale fait foi : le chiffre local reste à vérifier.', figureId: 'af_enfant' },
  ] }),
  lesson({ id: 'assur-lpp', competenceId: 'assurances', minutes: 6, concept: 'Le salaire coordonné LPP se calcule entre un seuil et un plafond.', de: { title: 'Koordinierter Lohn' }, checklist: ['Comparer le salaire au seuil d’entrée', 'Retirer la déduction de coordination', 'Borner le résultat'], source: BSV, screens: [
    { id: 's1', concept: 'Sous le seuil d’entrée, l’obligation légale ne s’ouvre pas.', title: '22 680 francs', body: 'Le document OFAS des montants au 1er janvier 2026 fixe le salaire minimal annuel à 22 680 francs. En dessous, le minimum LPP ne s’applique pas à ce seul emploi. Plusieurs emplois ou un plan plus généreux peuvent changer la situation : ce n’est pas une règle de temps partiel à inventer ici.', figureId: 'lpp_entry' },
    { id: 's2', concept: 'La déduction de coordination retire la part déjà couverte par l’AVS.', title: '26 460 francs', body: 'On ne cotise pas au minimum légal sur tout le brut. La déduction de coordination annuelle est de 26 460 francs. Le salaire coordonné ne descend pas sous 3 780 francs et le salaire pris en compte ne dépasse pas 90 720 francs dans le minimum légal.', figureId: 'lpp_coord' },
    { id: 's3', concept: 'La bonification d’épargne minimale dépend de l’âge.', title: '7, 10, 15, 18 pour cent', body: 'Le tableau OFAS donne, sur le salaire coordonné, 7 % de 25 à 34 ans, 10 % de 35 à 44 ans, 15 % de 45 à 54 ans et 18 % de 55 à 65 ans. C’est le total employeur et salarié. L’employeur doit au moins égaler l’ensemble des parts salariées. Le taux d’intérêt minimal de l’année est à vérifier à part.' },
  ] }),
  lesson({ id: 'paie-fiche', competenceId: 'paie', minutes: 6, concept: 'La fiche de salaire empile des retenues qui n’ont pas le même plafond.', de: { title: 'Lohnabrechnung lesen' }, checklist: ['Retenir 5,3 % sur tout le brut AVS', 'Arrêter l’AC au plafond', 'Laisser la LPP au règlement'], source: OFAS, screens: [
    { id: 's1', concept: 'AVS/AI/APG se calcule sur l’entier du salaire déterminant.', title: 'Pas de plafond AVS', body: 'La part salariée de 5,3 % s’applique sans le plafond de l’assurance-chômage. Un salaire élevé cotise donc davantage à l’AVS qu’à l’AC. La part employeur est égale sur le tableau 2026. Elle ne se déduit pas du net de la personne.', figureId: 'avs_ai_apg' },
    { id: 's2', concept: 'L’AC s’arrête au gain maximal assuré.', title: '1,1 % jusqu’à 148 200', body: 'La part salariée d’assurance-chômage est de 1,1 % sur la part du salaire jusqu’à 148 200 francs par an. Au-delà, le tableau OFAS ne prévoit pas de cotisation supplémentaire. Sur un mois, on plafonne l’assiette avant d’appliquer le taux. Le 13e salaire compte dans l’année.', figureId: 'ac_part' },
    { id: 's3', concept: 'La ligne LPP ne se devine pas à partir du seul âge.', title: 'Règlement de caisse', body: 'Les bonifications légales sont un minimum sur le salaire coordonné. La retenue réelle dépend du plan : part salariée, risques, frais, part surobligatoire. Sans le règlement, la ligne LPP de la fiche reste à vérifier. Il en va de même du taux AANP, propre à l’assureur.' },
  ] }),
  lesson({ id: 'paie-heure', competenceId: 'paie', minutes: 5, concept: 'L’heure supplémentaire du contrat n’est pas le travail supplémentaire de la LTr.', de: { title: 'Überstunden und Überzeit' }, checklist: ['Nommer la base : contrat ou plafond légal', 'Proposer d’abord la compensation en temps', 'N’écarter le quart que par écrit'], source: CO, screens: [
    { id: 's1', concept: 'L’heure au-delà du contrat se compense ou se paie avec un quart.', title: 'Article 321c', body: 'Si les circonstances exigent plus d’heures que le contrat, l’usage, le contrat-type ou la convention collective, la personne les exécute dans la mesure où elle le peut et où la bonne foi le permet. Avec son accord, l’employeur compense par un congé au moins égal, dans une période appropriée. Sinon, le salaire normal est majoré d’un quart au moins, sauf accord écrit, contrat-type ou convention collective.', figureId: 'ot_quarter' },
    { id: 's2', concept: 'Le supplément de la loi sur le travail vise le dépassement du maximum légal.', title: 'Article 13 LTr', body: 'Le travail supplémentaire de la loi sur le travail est autre chose : il dépasse la durée maximale légale. Le supplément d’au moins 25 % n’est dû au personnel de bureau, technique et de vente des grands commerces de détail qu’à partir de la soixante et unième heure de l’année civile. Une compensation en temps, avec accord, peut remplacer ce supplément.' },
    { id: 's3', concept: 'On n’additionne pas les deux majorations sans qualifier l’heure.', title: 'Une heure, un régime', body: 'Avant de calculer, on dit si l’heure dépasse seulement l’horaire convenu ou déjà le plafond de la loi sur le travail. Le certificat demande ce réflexe de paie. Inventer un taux unique de 25 % sur toutes les heures du mois mélange les deux régimes.' },
  ] }),
  lesson({ id: 'recrut-profil', competenceId: 'recrutement', minutes: 5, concept: 'Le profil d’exigences précède l’annonce et l’entretien.', de: { title: 'Anforderungsprofil' }, checklist: ['Séparer le nécessaire du souhaitable', 'Relier chaque critère à la tâche', 'Prévoir le même filtre pour tout le monde'], source: HRSE_B, screens: [
    { id: 's1', concept: 'La description de poste dit le travail, le profil dit ce qu’il faut pour le faire.', title: 'Deux documents', body: 'Les directives du brevet demandent de savoir élaborer une description de poste et un profil d’exigences. La description liste les tâches et le contexte. Le profil traduit ces tâches en compétences observables. Sans ce passage, l’annonce énumère des adjectifs.' },
    { id: 's2', concept: 'Un critère qui ne sert pas la tâche écarte des personnes sans raison.', title: 'Nécessaire ou habitude', body: 'Un diplôme, une langue ou une année d’expérience se justifie s’il conditionne le travail. Le reste se marque comme souhaitable. La loi sur l’égalité interdit de traiter différemment en raison du sexe dans l’embauche. Une exigence neutre en apparence se relit avec cet œil.' },
    { id: 's3', concept: 'L’annonce reprend le profil, elle ne le remplace pas.', title: 'Un public, un texte', body: 'Le brevet attend une annonce adaptée à un groupe cible, y compris via les canaux en ligne. On y met le travail, le lieu, le taux et la façon de postuler. On n’y met pas une photo exigée ni une question sur la famille. Le canal (site, réseau, école) se choisit après le profil, pas avant.' },
  ] }),
  lesson({ id: 'recrut-choix', competenceId: 'recrutement', minutes: 5, concept: 'La sélection compare les dossiers au profil, puis consigne l’entretien.', de: { title: 'Auswahl und Zeugnis' }, checklist: ['Trier avec la même grille', 'Noter des faits, pas une impression', 'Préparer le certificat sur le travail fait'], source: HRSE_B, screens: [
    { id: 's1', concept: 'La présélection applique le profil à chaque dossier.', title: 'Même grille', body: 'Les directives demandent des méthodes pour évaluer les dossiers et présélectionner. Une grille courte, tirée du profil, évite de changer de critère au troisième CV. Les données lues ne servent qu’à cette décision. La loi sur la protection des données limite ce que l’on conserve et à qui on le montre.' },
    { id: 's2', concept: 'L’entretien vérifie des faits que le dossier ne montre pas.', title: 'Questions liées au travail', body: 'On prépare un fil conducteur : motivation, exemples de travail, conditions. On n’interroge pas sur un projet de grossesse, une santé ou une origine pour écarter une candidature. À la fin, l’évaluation reprend les critères annoncés. Une note « bon feeling » ne se défend pas.' },
    { id: 's3', concept: 'Le certificat de travail décrit la prestation et la conduite.', title: 'Après le départ aussi', body: 'Le code des obligations donne droit à un certificat qui porte sur la nature et la durée du travail, la qualité du travail et la conduite. Il doit être vrai et bienveillant dans la forme. On le prépare à partir des faits observés, pas d’un modèle recopié. Les formules codées qui cachent un reproche ne sont pas une méthode enseignée ici.' },
  ] }),
  lesson({ id: 'fin-delais', competenceId: 'contrat-fin', minutes: 6, concept: 'Le délai de congé dépend du temps d’essai puis des années de service.', de: { title: 'Kündigungsfristen' }, checklist: ['Sept jours pendant l’essai', 'Un, deux, puis trois mois', 'Fin de mois après l’essai'], source: CO, screens: [
    { id: 's1', concept: 'Le temps d’essai légal est le premier mois, prolongeable jusqu’à trois.', title: 'Sept jours', body: 'Pendant le temps d’essai, chaque partie résilie à tout moment avec un délai de sept jours. Le premier mois est le temps d’essai, sauf accord écrit, contrat-type ou convention collective. Il ne peut pas dépasser trois mois. Une maladie, un accident ou une obligation légale non demandée pendant l’essai le prolonge d’autant.', figureId: 'notice_trial' },
    { id: 's2', concept: 'Après l’essai, le congé vise la fin d’un mois.', title: '1, 2, 3 mois', body: 'L’article 335c fixe un mois la première année de service, deux mois de la deuxième à la neuvième, trois mois ensuite. Le contrat peut être résilié pour la fin d’un mois. Un écrit peut modifier ces délais. Un délai inférieur à un mois ne se prévoit, pour la première année seulement, que par convention collective.', figureId: 'notice_y1' },
    { id: 's3', concept: 'On compte les années de service avant d’annoncer une date.', title: 'La date de fin', body: 'On part du jour où le congé est reçu, on ajoute le délai, puis on va à la fin du mois si le délai aboutit en cours de mois. Exemple de structure : un congé reçu le 10 mars en deuxième année (deux mois) ne finit pas le 10 mai. Le détail du jour de réception et des jours fériés de notification se vérifie sur le texte et la jurisprudence, sans raccourci.' },
  ] }),
  lesson({ id: 'fin-protection', competenceId: 'contrat-fin', minutes: 6, concept: 'Après l’essai, l’employeur ne peut pas résilier pendant certaines périodes.', de: { title: 'Kündigung zur Unzeit' }, checklist: ['30, 90 ou 180 jours selon l’année', 'Grossesse et seize semaines', 'Congé nul, délai suspendu'], source: CO, screens: [
    { id: 's1', concept: 'La maladie et l’accident ouvrent une protection limitée dans le temps.', title: '30, 90, 180', body: 'Après le temps d’essai, l’employeur ne résilie pas pendant une incapacité totale ou partielle due à une maladie ou un accident non fautif : 30 jours la première année de service, 90 jours de la deuxième à la cinquième, 180 jours dès la sixième. Ce n’est pas un maintien du salaire de la même durée. Ce sont deux questions.', figureId: 'prot_y1' },
    { id: 's2', concept: 'La grossesse et les semaines après la naissance bloquent le congé de l’employeur.', title: 'Seize semaines', body: 'L’article 336c vise aussi la grossesse et les seize semaines qui suivent l’accouchement, ainsi que le congé de maternité prolongé si le nouveau-né est hospitalisé. D’autres périodes existent : service long, congé de prise en charge d’un enfant gravement atteint, congé en cas de décès de la mère. On les lit dans l’article, on ne les résume pas en une seule formule.' },
    { id: 's3', concept: 'Un congé donné pendant la période est nul. Un délai en cours s’arrête.', title: 'Nul, puis suspendu', body: 'Le congé donné pendant une période protégée est nul. S’il a été donné avant et que le délai n’est pas écoulé quand la période commence, le délai est suspendu et ne reprend qu’après. S’il doit finir à un terme, comme la fin d’un mois, et que ce terme ne tombe pas à la fin du délai repris, on prolonge jusqu’au prochain terme.' },
  ] }),
  lesson({ id: 'abs-salaire', competenceId: 'absences', minutes: 6, concept: 'Le maintien du salaire en cas d’empêchement personnel est limité, puis souvent relayé.', de: { title: 'Lohnfortzahlung' }, checklist: ['Vérifier les trois mois de rapports', 'Trois semaines la première année', 'Chercher ensuite CCT ou assurance'], source: CO, screens: [
    { id: 's1', concept: 'L’employeur paie un temps limité si l’empêchement n’est pas fautif.', title: 'Article 324a', body: 'Maladie, accident, obligation légale ou fonction publique : si la personne est empêchée sans faute, l’employeur verse le salaire pour un temps limité, y compris une indemnité pour le salaire en nature perdu. Encore faut-il que les rapports aient duré plus de trois mois ou soient conclus pour plus de trois mois.' },
    { id: 's2', concept: 'La première année, la loi chiffre trois semaines.', title: 'Ensuite, une durée équitable', body: 'Sauf délai plus long convenu, l’employeur paie trois semaines la première année de service, puis une période plus longue fixée équitablement selon la durée des rapports et les circonstances. Les échelles dites de Berne, Bâle ou Zurich ne sont pas dans l’article : elles restent à vérifier avant d’être appliquées.', figureId: 'salary_w1' },
    { id: 's3', concept: 'Une assurance peut remplacer ce maintien si elle est au moins équivalente.', title: 'Ne pas payer deux fois sans lire', body: 'Un accord écrit, un contrat-type ou une convention collective peut déroger s’il accorde des prestations au moins équivalentes. Une indemnité journalière maladie n’a pas de taux fédéral unique : police ou CCT, à vérifier. L’accident professionnel suit la LAA, pas cette ligne maladie.' },
  ] }),
  lesson({ id: 'abs-conges', competenceId: 'absences', minutes: 6, concept: 'Les congés familiaux du code ont une durée et une fenêtre.', de: { title: 'Familienurlaube' }, checklist: ['Quatre ou cinq semaines de vacances', 'Quatorze semaines de maternité', 'Deux semaines pour l’autre parent'], source: CO, screens: [
    { id: 's1', concept: 'Les vacances minimales sont de quatre semaines, cinq jusqu’à 20 ans révolus.', title: 'Article 329a', body: 'Chaque année de service donne quatre semaines au moins, et cinq semaines au moins jusqu’à l’âge de 20 ans révolus. Si l’année n’est pas complète, les vacances sont proportionnelles à la durée des rapports. Une absence fautive de plus d’un mois peut réduire d’un douzième par mois complet. La maladie non fautive d’un mois au plus ne réduit pas.', figureId: 'vac_adult' },
    { id: 's2', concept: 'Le congé de maternité dure au moins quatorze semaines après la naissance.', title: 'Article 329f', body: 'Il se prolonge si le nouveau-né est hospitalisé, dans la mesure de l’allocation. L’allocation lue sur la page OFAS est de 80 % du revenu, au plus 220 francs par jour. Le mémento 6.02 porte encore la mention d’état au 1er janvier 2025 : on revérifie le plafond chaque année.', figureId: 'mat_weeks' },
    { id: 's3', concept: 'L’autre parent a deux semaines dans les six mois.', title: 'Article 329g', body: 'Le père légal, ou l’autre parent légal, prend deux semaines dans les six mois, en semaines ou en jours. Un congé payé pour un proche malade ne dépasse pas trois jours par cas et dix jours par année. Le congé pour un enfant gravement atteint, lorsqu’une allocation est due, peut aller jusqu’à quatorze semaines dans un délai-cadre de dix-huit mois.', figureId: 'parent_weeks' },
  ] }),
  lesson({ id: 'egal-cycle', competenceId: 'egalite-donnees', minutes: 5, concept: 'Égalité et protection des données s’appliquent de l’annonce au certificat.', de: { title: 'Gleichstellung und Daten' }, checklist: ['Relire l’annonce et les questions', 'Limiter les données au besoin', 'Dire qui y accède'], source: LEG, screens: [
    { id: 's1', concept: 'L’égalité vise l’embauche, le salaire, la formation et le congé.', title: 'Pas seulement le recrutement', body: 'La loi sur l’égalité s’applique au rapport de travail, pas à une seule étape. Une différence de salaire, une mise à l’écart d’une formation ou un congé lié au sexe posent la même question que l’annonce. Le harcèlement sexuel est aussi visé par cette loi. Le texte public est sur Fedlex ; on ne le remplace pas par un résumé d’école.' },
    { id: 's2', concept: 'On ne traite que les données utiles au but annoncé.', title: 'Dossier personnel', body: 'La loi sur la protection des données encadre les données des candidatures et du personnel. On collecte ce qui sert la décision, on informe, on limite l’accès, on fixe une durée de conservation. Un tableau partagé avec toute l’équipe « pour info » n’est pas un motif. Les numéros d’articles précis de la LPD restent à relire sur Fedlex avant un cas réel.' },
    { id: 's3', concept: 'Le brevet attend ces deux lois sur tout le cycle.', title: 'Base 1', body: 'Les directives 2023 placent l’égalité et la protection des données dans les connaissances de base, pour le placement, l’embauche, l’emploi et la résiliation. Ce n’est pas une option de spécialisation. Le certificat les croise dans le droit du travail et l’administration du personnel.' },
  ] }),
  lesson({ id: 'dev-besoin', competenceId: 'developpement', minutes: 5, concept: 'Un besoin de développement se formule à partir du travail, puis se situe dans le système suisse.', de: { title: 'Entwicklungsbedarf' }, checklist: ['Partir d’une tâche manquante', 'Distinguer lieu de travail et cours', 'Situer le diplôme suisse'], source: HRSE_B, screens: [
    { id: 's1', concept: 'On décrit l’écart entre le travail demandé et ce que la personne fait déjà.', title: 'Un fait, pas une étiquette', body: 'Les directives demandent d’analyser les besoins de développement et le potentiel. On part d’une tâche : un entretien difficile, un outil de paie, une langue du poste. « Manque de motivation » n’est pas un besoin de formation. Le potentiel se discute avec la personne et le supérieur, sur des exemples.' },
    { id: 's2', concept: 'La mesure peut être sur le lieu de travail ou au-dehors.', title: 'Court ou diplômant', body: 'Une revue de dossier avec un pair, une mission, un cours d’une journée et un diplôme sont des réponses différentes. Le brevet attend une connaissance de base de ces mesures. On choisit la plus courte qui comble l’écart, et on fixe qui paie et quand le travail reprend.' },
    { id: 's3', concept: 'Le système suisse a ses propres titres.', title: 'CFC, certificat, brevet', body: 'Le certificat HRSE de gestionnaire RH et le brevet fédéral de spécialiste RH sont deux titres. Le premier est un certificat d’association et une voie d’admission au second. Reconnaître un diplôme étranger passe par les organismes indiqués par les autorités, pas par une équivalence improvisée. Les adresses précises se vérifient au moment du dossier.' },
  ] }),
  lesson({ id: 'com-entretien', competenceId: 'communication', minutes: 5, concept: 'Un entretien professionnel se prépare, se structure et se relit.', de: { title: 'Gespräch vorbereiten' }, checklist: ['Clarifier le but et les rôles', 'Poser des questions liées aux faits', 'Noter la suite'], source: HRSE_B, screens: [
    { id: 's1', concept: 'La préparation fixe le but, les rôles et le lieu.', title: 'Avant la porte', body: 'Base 2 des directives : préparer l’entretien sur le fond et sur l’organisation. On écrit le but en une phrase, qui parle, combien de temps, quels documents. Pour un entretien d’embauche, le fil conducteur est partagé avec le supérieur avant, pas inventé dans le couloir.' },
    { id: 's2', concept: 'Pendant l’entretien, on reste sur des faits et on laisse parler.', title: 'Questions ouvertes, puis précises', body: 'On accueille, on rappelle le déroulement, on pose une question ouverte, on demande un exemple. En cas de tension, on nomme le sujet et on propose une pause plutôt que de hausser le ton. La négociation du salaire reste dans le cadre donné par l’employeur. L’estime et la confidentialité font partie de la compétence décrite par HRSE, pas d’un style personnel.' },
    { id: 's3', concept: 'Après, on compare ce qui a été dit aux critères prévus.', title: 'La relecture', body: 'L’épreuve orale du brevet montre une situation d’entretien et demande les forces, les faiblesses et des améliorations. S’entraîner, c’est donc relire : le but était-il clair, la personne a-t-elle pu parler, la suite est-elle datée. Une bonne impression générale ne répond pas à la question.' },
  ] }),
  lesson({ id: 'etr-permis', competenceId: 'etrangers', minutes: 6, concept: 'Le régime d’autorisation n’est pas le même pour l’UE/AELE et pour les autres États.', de: { title: 'Bewilligungen' }, checklist: ['Séparer ALCP et LEI', 'Ne pas citer un quota de mémoire', 'Vérifier le permis avant le premier jour'], source: ALCP, screens: [
    { id: 's1', concept: 'L’accord sur la libre circulation organise l’emploi des ressortissants UE et AELE.', title: 'Pas le même dossier', body: 'Les directives du brevet demandent les règles d’embauche des personnes venant de l’UE, de l’AELE et des pays tiers. L’ALCP et la LEI ne s’ouvrent pas sur le même formulaire. Avant une promesse d’embauche, on identifie la nationalité, le lieu de résidence et le type d’activité. Le texte des deux actes est sur Fedlex.' },
    { id: 's2', concept: 'Les permis ont des noms stables et des durées qui se vérifient.', title: 'L, B, C, G', body: 'On parle couramment de permis de courte durée, de séjour, d’établissement et de frontalier. Les conditions exactes, les délais et les changements de canton se lisent dans la LEI, ses ordonnances et la pratique du SEM. Cette leçon ne fige pas une durée : elle apprend à aller chercher la catégorie avant de rédiger le contrat.' },
    { id: 's3', concept: 'Les contingents annuels des États tiers ne s’apprennent pas comme un taux.', title: 'À vérifier chaque année', body: 'Le nombre de permis pour les États tiers est fixé par les autorités et change. Il est marqué à vérifier dans les fiches de l’app. Annoncer un quota de l’an dernier dans un conseil d’embauche est une erreur de méthode, même si le reste du dossier est juste.', figureId: 'lei_quota' },
  ] }),
  lesson({ id: 'cct-role', competenceId: 'cct', minutes: 5, concept: 'Une convention collective peut améliorer le minimum légal et, si elle est étendue, lier d’autres employeurs.', de: { title: 'Gesamtarbeitsvertrag' }, checklist: ['Vérifier si une CCT s’applique', 'Comparer délai et vacances au CO', 'Chercher une extension avant un salaire minimum'], source: CO, screens: [
    { id: 's1', concept: 'La CCT est un accord collectif, pas un règlement interne.', title: 'Partenaires', body: 'Les directives demandent de connaître les contrats individuels, les conventions collectives et la question du salaire minimum. La CCT est négociée entre employeurs ou associations et syndicats. Elle peut fixer des salaires, des vacances ou des délais plus favorables que le code. Un règlement d’entreprise unilatéral n’est pas une CCT.' },
    { id: 's2', concept: 'Certaines règles du code ne se baissent pas librement.', title: 'Le plancher reste', body: 'L’article 335c permet des délais différents par écrit, mais un délai inférieur à un mois, la première année, seulement par convention collective. D’autres articles sont impératifs en faveur de la personne employée. Avant de « déroger », on lit si la loi l’autorise. Le détail des articles impératifs se vérifie dans le code, titre dixième.' },
    { id: 's3', concept: 'Il n’y a pas de salaire minimum fédéral général.', title: 'CCT ou canton', body: 'Sans CCT applicable ni règle cantonale, on ne cite pas un minimum national. L’extension d’une CCT à toute une branche se décide selon la loi fédérale prévue à cet effet. Le montant et le champ d’application se lisent dans l’arrêté et le texte de la CCT, pas dans une leçon. C’est marqué à vérifier cas par cas.', figureId: 'salaire_min' },
  ] }),
  lesson({ id: 'proc-chiffre', competenceId: 'processus', minutes: 5, concept: 'Un indicateur RH se définit avant de se comparer.', de: { title: 'Kennzahlen' }, checklist: ['Écrire la formule', 'Dire la période et le périmètre', 'Ne pas inventer une norme'], source: HRSE_B, screens: [
    { id: 's1', concept: 'Un processus se raconte en étapes et en responsables.', title: 'De la demande au contrat', body: 'L’approfondissement A4 vise la collaboration dans les processus, les projets et les systèmes. On décrit une embauche en étapes courtes : besoin, profil, annonce, tri, entretien, décision, contrat, accueil. Chaque étape a une personne responsable et une donnée produite. C’est déjà un processus, sans logiciel.' },
    { id: 's2', concept: 'Un chiffre clé a une formule, une date et un périmètre.', title: 'Lire avant de juger', body: 'Le taux de rotation, le délai d’embauche ou le coût d’une absence ne veulent rien sans la formule. « Départs de l’année divisés par l’effectif moyen » n’est pas « départs du mois ». Les directives parlent d’un ordre de grandeur pour comparer. Elles ne publient pas un bon taux universel. Un benchmark non sourcé reste à vérifier.' },
    { id: 's3', concept: 'Le coût et le bénéfice se disent avec les hypothèses.', title: 'Une phrase de controlling', body: 'Base 1 demande une compréhension de base des considérations coût-bénéfice. Exemple : un cours de deux jours coûte le prix et deux jours de travail ; il évite une erreur de paie répétée. On chiffre les deux côtés et on dit ce que l’on n’a pas mesuré. La protection des données s’applique aux tableaux nominatifs exportés pour « le controlling ».' },
  ] }),
  lesson({ id: 'markt-cible', competenceId: 'marketing-rh', minutes: 4, concept: 'Le marketing RH formule une promesse vérifiable pour un public précis.', de: { title: 'Zielgruppe ansprechen' }, checklist: ['Nommer le public', 'N’écrire que ce que l’entreprise fait', 'Relire l’égalité'], source: HRSE_B, screens: [
    { id: 's1', concept: 'On choisit un public avant le slogan.', title: 'Qui doit se reconnaître', body: 'Les directives parlent d’annonces adaptées à un groupe cible et de l’image portée par les spécialistes RH. Le marketing RH, dans cette leçon, c’est cela : un message pour des personnes qui peuvent faire le travail. « Jeunes dynamiques » ne désigne pas une compétence et peut écarter. On préfère le métier, le lieu et ce qui est vraiment offert.' },
    { id: 's2', concept: 'La promesse doit être vraie dans le quotidien.', title: 'Pas une brochure', body: 'Horaires, télétravail, formation : on n’écrit que ce que le contrat et l’équipe confirment. Cette zone du parcours est encore mince. Elle ne remplace pas un cours de marque employeur. Elle évite l’annonce qui contredit le profil d’exigences vu dans le module recrutement.' },
  ] }),
  lesson({ id: 'place-options', competenceId: 'placement', minutes: 5, concept: 'Les options B et C du brevet ne font pas le même métier que l’option A.', de: { title: 'Optionen B und C' }, checklist: ['Distinguer ORP, placement privé et location', 'Garder Base 1 pour tout le monde', 'Chercher la LSE avant un conseil'], source: HRSE_B, screens: [
    { id: 's1', concept: 'L’option A accompagne le cycle du personnel dans l’entreprise.', title: 'Trois métiers', body: 'La page HRSE décrit trois options. A : recrutement, organisation, évaluation, développement, rémunération et séparation dans l’entreprise. B : conseil et placement des demandeurs d’emploi, avec la LACI. C : placement privé et location de services, y compris la gestion du personnel temporaire et de l’unité. Le même brevet, pas le même cas pratique.' },
    { id: 's2', concept: 'Les épreuves 2 et 3 suivent l’option. L’épreuve 1 est commune.', title: 'Ce que cette leçon ne fait pas', body: 'L’épreuve 1, 180 minutes, porte sur Base 1 pour tout le monde. L’étude de cas et les mini-cas portent sur les champs de l’option. Cette leçon ne simule pas un dossier ORP ni un contrat de location de services complet : ces deux pratiques restent minces dans l’app. Les textes LACI et LSE sur Fedlex sont le point de départ, pas un script d’entretien.' },
  ] }),
];

const cards: CardItem[] = [
  { id: 'c-contrat', competenceId: 'droit-travail', front: 'Que faut-il pour qu’un contrat de travail existe ?', back: 'Un travail au service d’autrui contre un salaire, selon le temps ou le travail. Forme libre, sauf exception légale.', de: { front: 'Wann entsteht ein Arbeitsvertrag?' }, source: CO },
  { id: 'c-45', competenceId: 'droit-travail', front: 'Durée maximale hebdomadaire du personnel de bureau ?', back: '45 heures (LTr art. 9). 50 heures pour les autres travailleurs.', de: { front: 'Höchstarbeitszeit Büro?' }, figureId: 'ltr_45', source: LTR },
  { id: 'c-pause', competenceId: 'droit-travail', front: 'Pause minimale si la journée dépasse sept heures ?', back: 'Une demi-heure (LTr art. 15). Un quart d’heure au-delà de 5 h 30, une heure au-delà de 9 h.', de: { front: 'Pause ab sieben Stunden?' }, source: LTR },
  { id: 'c-repos', competenceId: 'droit-travail', front: 'Repos quotidien ordinaire ?', back: 'Onze heures consécutives. Huit heures une fois par semaine possible si la moyenne sur deux semaines reste à onze.', de: { front: 'Tägliche Ruhezeit?' }, figureId: 'ltr_rest', source: LTR },
  { id: 'c-53', competenceId: 'assurances', front: 'Part salariée AVS/AI/APG en 2026 ?', back: '5,3 % (4,35 + 0,7 + 0,25), sans plafond de salaire. Part employeur égale.', de: { front: 'AHV/IV/EO Arbeitnehmendenanteil 2026?' }, figureId: 'avs_ai_apg', source: OFAS },
  { id: 'c-ac', competenceId: 'assurances', front: 'Jusqu’où cotise l’AC en 2026 ?', back: '1,1 % salarié et 1,1 % employeur jusqu’à 148 200 francs par an.', de: { front: 'ALV-Höchstgrenze?' }, figureId: 'ac_ceiling', source: OFAS },
  { id: 'c-lpp-seuil', competenceId: 'assurances', front: 'Seuil d’entrée LPP au 1.1.2026 ?', back: '22 680 francs de salaire annuel. Coordination 26 460. Coordonné minimal 3 780. Plafond 90 720.', de: { front: 'BVG-Eintrittsschwelle?' }, figureId: 'lpp_entry', source: BSV },
  { id: 'c-af', competenceId: 'assurances', front: 'Minimum fédéral des allocations familiales ?', back: '215 francs par mois pour l’enfant, 268 pour la formation. Le canton peut être plus élevé : à vérifier.', de: { front: 'Mindestansätze Familienzulagen?' }, figureId: 'af_enfant', source: LAFAM },
  { id: 'c-ac-mois', competenceId: 'paie', front: 'Comment plafonner l’AC sur un mois ?', back: 'On ne prend que la part du salaire encore sous le plafond annuel, puis 1,1 %.', de: { front: 'ALV unter dem Jahr deckeln?' }, source: OFAS },
  { id: 'c-quart', competenceId: 'paie', front: 'Majoration CO des heures non compensées ?', back: 'Au moins un quart, sauf accord écrit, contrat-type ou convention collective (art. 321c).', de: { front: 'Zuschlag Überstunden OR?' }, figureId: 'ot_quarter', source: CO },
  { id: 'c-sur', competenceId: 'paie', front: 'Le supplément LTr de 25 % est-il dû dès la première heure de bureau ?', back: 'Non. Pour le personnel de bureau, seulement à partir de la 61e heure supplémentaire de l’année civile, et il s’agit du dépassement du maximum légal.', de: { front: 'Überzeitzuschlag ab der ersten Stunde?' }, source: LTR },
  { id: 'c-lpp-ligne', competenceId: 'paie', front: 'Peut-on calculer la retenue LPP avec le seul âge ?', back: 'Non. L’âge donne la bonification minimale totale. La ligne de la fiche suit le règlement de caisse.', de: { front: 'BVG-Abzug nur nach Alter?' }, source: BSV },
  { id: 'c-profil', competenceId: 'recrutement', front: 'Quelle est la différence entre description de poste et profil ?', back: 'La description dit le travail. Le profil dit les compétences nécessaires pour le faire.', de: { front: 'Stelle und Anforderung?' }, source: HRSE_B },
  { id: 'c-grille', competenceId: 'recrutement', front: 'À quoi sert la grille de présélection ?', back: 'À appliquer les mêmes critères du profil à chaque dossier, et à limiter les données utilisées.', de: { front: 'Wozu ein Auswahlraster?' }, source: LPD },
  { id: 'c-certif', competenceId: 'recrutement', front: 'Que doit permettre un certificat de travail ?', back: 'Connaître la nature, la durée, la qualité du travail et la conduite, de façon vraie.', de: { front: 'Inhalt des Arbeitszeugnisses?' }, source: CO },
  { id: 'c-feeling', competenceId: 'recrutement', front: '« Bon feeling » suffit-il comme motif de refus ?', back: 'Non. On revient aux critères annoncés et à des faits observés.', de: { front: 'Reicht ein gutes Gefühl?' }, source: LEG },
  { id: 'c-essai', competenceId: 'contrat-fin', front: 'Délai pendant le temps d’essai ?', back: 'Sept jours. Temps d’essai légal : un mois, au plus trois par accord.', de: { front: 'Frist in der Probezeit?' }, figureId: 'notice_trial', source: CO },
  { id: 'c-335c', competenceId: 'contrat-fin', front: 'Délais après l’essai ?', back: '1 mois la 1re année, 2 mois de la 2e à la 9e, 3 mois ensuite, pour la fin d’un mois.', de: { front: 'Fristen nach der Probezeit?' }, figureId: 'notice_y2', source: CO },
  { id: 'c-336c', competenceId: 'contrat-fin', front: 'Protection en cas de maladie après l’essai ?', back: '30 jours la 1re année, 90 jours de la 2e à la 5e, 180 jours dès la 6e.', de: { front: 'Sperrfrist Krankheit?' }, figureId: 'prot_y2', source: CO },
  { id: 'c-nul', competenceId: 'contrat-fin', front: 'Effet d’un congé donné pendant la protection ?', back: 'Il est nul. S’il a été donné avant, le délai se suspend et reprend après la période.', de: { front: 'Kündigung während Sperrfrist?' }, source: CO },
  { id: 'c-324a', competenceId: 'absences', front: 'Maintien du salaire la première année ?', back: 'Trois semaines si les rapports durent ou sont conclus pour plus de trois mois. Ensuite, durée équitable : échelles à vérifier.', de: { front: 'Lohnfortzahlung im ersten Jahr?' }, figureId: 'salary_w1', source: CO },
  { id: 'c-vac', competenceId: 'absences', front: 'Vacances minimales ?', back: '4 semaines par année de service, 5 jusqu’à 20 ans révolus. Prorata si l’année est incomplète.', de: { front: 'Mindestferien?' }, figureId: 'vac_young', source: CO },
  { id: 'c-mat', competenceId: 'absences', front: 'Congé de maternité et plafond d’allocation lus en 2026 ?', back: 'Au moins 14 semaines. Allocation 80 %, au plus 220 francs par jour selon la page OFAS.', de: { front: 'Mutterschaftsurlaub und Höchstansatz?' }, figureId: 'amat_cap', source: CO },
  { id: 'c-parent', competenceId: 'absences', front: 'Congé de l’autre parent ?', back: 'Deux semaines dans les six mois, en semaines ou en jours.', de: { front: 'Urlaub des anderen Elternteils?' }, figureId: 'parent_weeks', source: CO },
  { id: 'c-leg', competenceId: 'egalite-donnees', front: 'L’égalité s’arrête-t-elle à l’annonce ?', back: 'Non. Embauche, salaire, formation, congé et harcèlement sont dans le même cycle.', de: { front: 'Nur die Stellenanzeige?' }, source: LEG },
  { id: 'c-lpd', competenceId: 'egalite-donnees', front: 'Que faire d’une donnée de candidature inutile ?', back: 'Ne pas la collecter, ou ne pas la conserver. L’accès se limite au besoin du dossier.', de: { front: 'Unnötige Bewerbungsdaten?' }, source: LPD },
  { id: 'c-base1', competenceId: 'egalite-donnees', front: 'Où HRSE place l’égalité et la LPD ?', back: 'Dans Base 1, pour toutes les options du brevet, sur tout le cycle du personnel.', de: { front: 'Wo stehen GlG und DSG?' }, source: HRSE_B },
  { id: 'c-ecart', competenceId: 'developpement', front: 'Comment formuler un besoin de développement ?', back: 'À partir d’une tâche que la personne ne fait pas encore, pas d’une étiquette.', de: { front: 'Entwicklungsbedarf formulieren?' }, source: HRSE_B },
  { id: 'c-titres', competenceId: 'developpement', front: 'Le certificat HRSE est-il le brevet fédéral ?', back: 'Non. C’est un certificat d’association, et l’une des conditions d’admission au brevet.', de: { front: 'Zertifikat gleich Fachausweis?' }, source: HRSE_C },
  { id: 'c-mesure', competenceId: 'developpement', front: 'Toute lacune appelle-t-elle un diplôme ?', back: 'Non. On choisit la mesure la plus courte qui comble l’écart de travail.', de: { front: 'Immer ein Diplom?' }, source: HRSE_B },
  { id: 'c-but', competenceId: 'communication', front: 'Que prépare-t-on avant un entretien ?', back: 'Le but en une phrase, les rôles, la durée et les documents.', de: { front: 'Vorbereitung eines Gesprächs?' }, source: HRSE_B },
  { id: 'c-oral', competenceId: 'communication', front: 'Que demande la réflexion orale du brevet ?', back: 'Forces, faiblesses et améliorations d’une situation d’entretien, après 20 minutes de préparation.', de: { front: 'Mündliche Reflexion?' }, source: HRSE_B },
  { id: 'c-ton', competenceId: 'communication', front: 'Que faire si l’entretien se tend ?', back: 'Nommer le sujet et proposer une pause, sans quitter le cadre professionnel.', de: { front: 'Wenn das Gespräch kippt?' }, source: HRSE_B },
  { id: 'c-alcp', competenceId: 'etrangers', front: 'ALCP et LEI, même dossier ?', back: 'Non. UE/AELE et États tiers ne suivent pas le même régime. On identifie la nationalité d’abord.', de: { front: 'FZA und AIG gleich?' }, source: ALCP },
  { id: 'c-quota', competenceId: 'etrangers', front: 'Peut-on apprendre le contingent de permis par cœur ?', back: 'Non. Il est annuel et marqué à vérifier. On consulte l’arrêté de l’année.', de: { front: 'Kontingent auswendig?' }, figureId: 'lei_quota', source: LEI },
  { id: 'c-avant', competenceId: 'etrangers', front: 'Quand vérifier le permis ?', back: 'Avant le premier jour de travail et avant de promettre une date d’entrée.', de: { front: 'Wann die Bewilligung prüfen?' }, source: LEI },
  { id: 'c-gav', competenceId: 'cct', front: 'Une CCT peut-elle allonger les vacances ?', back: 'Oui, au-delà du minimum du code. Elle ne peut pas baisser un minimum impératif.', de: { front: 'Mehr Ferien im GAV?' }, source: CO },
  { id: 'c-delai-cct', competenceId: 'cct', front: 'Qui peut prévoir un délai inférieur à un mois la première année ?', back: 'Seulement une convention collective (art. 335c al. 2).', de: { front: 'Kürzere Frist im ersten Jahr?' }, source: CO },
  { id: 'c-min', competenceId: 'cct', front: 'Y a-t-il un salaire minimum fédéral général ?', back: 'Non. CCT, extension ou droit cantonal : à vérifier pour le cas.', de: { front: 'Landesweiter Mindestlohn?' }, figureId: 'salaire_min', source: CO },
  { id: 'c-formule', competenceId: 'processus', front: 'Que faut-il pour lire un taux de rotation ?', back: 'La formule, la période et le périmètre. Pas une « bonne » valeur universelle.', de: { front: 'Fluktuation lesen?' }, source: HRSE_B },
  { id: 'c-etapes', competenceId: 'processus', front: 'Quelle est la plus petite description d’un processus d’embauche ?', back: 'Besoin, profil, annonce, tri, entretien, décision, contrat, accueil, avec un responsable par étape.', de: { front: 'Recruiting-Ablauf?' }, source: HRSE_B },
  { id: 'c-export', competenceId: 'processus', front: 'Un export nominatif « pour le controlling » est-il anodin ?', back: 'Non. La protection des données s’applique. On limite les colonnes et les lecteurs.', de: { front: 'Personenbezogener Export?' }, source: LPD },
  { id: 'c-slogan', competenceId: 'marketing-rh', front: 'Par quoi commencer une annonce employeur ?', back: 'Par le public et par des faits vérifiables, pas par un adjectif.', de: { front: 'Womit eine Anzeige beginnen?' }, source: HRSE_B },
  { id: 'c-vrai', competenceId: 'marketing-rh', front: 'Peut-on promettre le télétravail dans l’annonce ?', back: 'Seulement s’il est réel dans le contrat et l’équipe.', de: { front: 'Homeoffice versprechen?' }, source: HRSE_C },
  { id: 'c-opt', competenceId: 'placement', front: 'Quelle option du brevet concerne l’ORP ?', back: 'L’option B, placement public et conseil, avec la LACI.', de: { front: 'Welche Option für das RAV?' }, source: HRSE_B },
  { id: 'c-commun', competenceId: 'placement', front: 'Quelle épreuve est commune aux trois options ?', back: 'L’épreuve 1, connaissances générales, 180 minutes, champ Base 1.', de: { front: 'Gemeinsame Prüfung?' }, source: HRSE_B },
];

