export const catalog: Catalog = {
  catalogVersion: 1,
  consultedAt: DAY,
  localePrimary: 'fr',
  german: 'structure_ready',
  figures: [...FIGURES, ...accountingFigures],
  competences: [...competences, accountingCompetence],
  lessons: [...lessons, ...accountingLessons],
  cards: [...cards, ...accountingCards],
  drills: [...drills, ...accountingDrills],
  cases,
  exams: [...exams, ...accountingExams],
};

export function findCompetence(id: string) {
  return catalog.competences.find((item) => item.id === id);
}
export function findLesson(id: string) {
  return catalog.lessons.find((item) => item.id === id);
}
export function findDrill(id: string) {
  return catalog.drills.find((item) => item.id === id);
}
export function findCase(id: string) {
  return catalog.cases.find((item) => item.id === id);
}
export function findExam(id: string) {
  return catalog.exams.find((item) => item.id === id);
}
export function cardsFor(competenceId: string) {
  return catalog.cards.filter((card) => card.competenceId === competenceId);
}
